/** Accessible first-party visitor notes. The garden owns movement and modal lifecycle. */
export function createVisitorBoardUI({onOpen=()=>{},onClose=()=>{},onChange=()=>{}}={}) {
  const dialog=document.createElement('dialog');dialog.id='visitor-board';dialog.className='vb-dialog';dialog.setAttribute('aria-labelledby','vb-title');
  dialog.innerHTML=`<div class="vb-shell"><header class="vb-header"><div><p class="vb-eyebrow">THE VISITOR BOARD</p><h1 id="vb-title">Your ride. Your say.</h1><p>Found a favourite corner? Spotted something to improve? Your feedback helps shape the next ride.</p></div><button type="button" class="vb-close" data-vb-close>Back to the garden</button></header><p class="vb-preview" hidden>Local test version. Notes stay in this preview and are not published to the live website.</p><div class="vb-columns"><section aria-labelledby="vb-recent-title"><div class="vb-section-title"><h2 id="vb-recent-title">Recent reviews</h2><button type="button" data-vb-refresh>Refresh</button></div><p class="vb-load-status" role="status"></p><div class="vb-list"></div></section><section class="vb-write" aria-labelledby="vb-write-title"><h2 id="vb-write-title">Leave your review</h2><form class="vb-form"><label for="vb-name">Your name</label><input id="vb-name" name="name" autocomplete="name" required maxlength="60"><fieldset class="vb-rating"><legend>How was your experience?</legend><div>${[1,2,3,4,5].map(n=>`<label class="vb-star"><input type="radio" name="stars" value="${n}" required><span aria-hidden="true">&#9733;</span><span class="vb-star-number">${n}</span><span class="vb-sr-only">out of 5</span></label>`).join('')}</div></fieldset><label for="vb-feedback">Your feedback</label><textarea id="vb-feedback" name="feedback" rows="4" required minlength="10" maxlength="600" aria-describedby="vb-feedback-help"></textarea><p id="vb-feedback-help" class="vb-help">What worked? What would you change? 10–600 characters.</p><label for="vb-linkedin">LinkedIn profile <span class="vb-optional">(optional)</span></label><input id="vb-linkedin" name="linkedin" type="url" inputmode="url" autocomplete="url" placeholder="https://www.linkedin.com/in/your-name" aria-describedby="vb-linkedin-help"><p id="vb-linkedin-help" class="vb-help">Shown with your note, so visitors can view your profile.</p><label class="vb-consent"><input type="checkbox" name="consent" required><span>I agree to display my name, rating, feedback and optional LinkedIn link on this visitor board.</span></label><p class="vb-submit-status" role="status" tabindex="-1"></p><button type="submit" class="vb-submit">Pin my review</button></form></section></div></div>`;
  document.body.append(dialog);
  const q=s=>dialog.querySelector(s),form=q('form'),list=q('.vb-list'),loadStatus=q('.vb-load-status'),submitStatus=q('.vb-submit-status'),submit=q('.vb-submit');
  if(['localhost','127.0.0.1','[::1]'].includes(location.hostname))q('.vb-preview').hidden=false;
  const prompt=document.createElement('aside');prompt.className='vb-invite';prompt.hidden=true;prompt.setAttribute('aria-label','Optional visitor feedback');prompt.setAttribute('aria-live','polite');prompt.innerHTML='<div><strong>How was your ride?</strong><p>Leave a quick review, or see what other visitors noticed.</p></div><div class="vb-invite-actions"><button type="button" data-vb-invite-write>Read or leave a review</button><button type="button" data-vb-invite-skip>Continue without feedback</button></div>';document.body.append(prompt);
  let dead=false,busy=false,loaded=false,loadGeneration=0,lastFocus=null,leave=null,leaveAfterClose=null,loadAbort=null,postAbort=null;
  const text=(tag,value,parent,className)=>{const element=document.createElement(tag);if(className)element.className=className;element.textContent=value;parent.append(element);return element;};
  function linkedIn(value){if(!value?.trim())return '';try{const u=new URL(value.trim());if(u.protocol==='https:'&&/^(www\.)?linkedin\.com$/i.test(u.hostname)&&/^\/in\/[a-zA-Z0-9_-]+\/?$/.test(u.pathname)&&!u.username&&!u.password&&!u.port&&!u.search&&!u.hash)return 'https://www.linkedin.com'+u.pathname.replace(/\/$/,'');}catch{}return null;}
  function render(reviews){list.replaceChildren();if(!reviews.length){text('p','No reviews yet. Be the first to leave a thought for the next visitor.',list,'vb-empty');return;}for(const review of reviews){const card=document.createElement('article');card.className='vb-note';list.append(card);const top=document.createElement('div');top.className='vb-note-meta';card.append(top);text('h3',review.name,top);const rating=text('span',`${review.stars} / 5`,top,'vb-note-rating');rating.setAttribute('aria-label',`${review.stars} out of 5 stars`);text('p',review.feedback,card,'vb-note-body');const bottom=document.createElement('div');bottom.className='vb-note-bottom';card.append(bottom);const date=new Date(review.createdAt);if(Number.isFinite(date.getTime())){const time=text('time',new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(date),bottom);time.dateTime=date.toISOString();}const url=linkedIn(review.linkedin);if(url){const a=text('a','LinkedIn profile',bottom);a.href=url;a.target='_blank';a.rel='noopener noreferrer';}}}
  async function refresh(){if(dead)return [];const generation=++loadGeneration;loadAbort?.abort();loadAbort=new AbortController();loadStatus.textContent='Loading visitor notes...';q('[data-vb-refresh]').disabled=true;
    try{const response=await fetch('/api/reviews',{signal:loadAbort.signal,cache:'no-store',credentials:'same-origin'});if(!response.ok)throw Error('load');const data=await response.json();if(!Array.isArray(data.reviews))throw Error('shape');const reviews=data.reviews.filter(r=>r&&typeof r.name==='string'&&typeof r.feedback==='string'&&Number.isInteger(r.stars)&&r.stars>=1&&r.stars<=5).slice(0,20);if(dead||generation!==loadGeneration)return [];loaded=true;render(reviews);loadStatus.textContent=reviews.length?`${reviews.length} recent ${reviews.length===1?'note':'notes'}. Newest first.`:'No visitor notes yet.';onChange(reviews);return reviews;}
    catch(error){if(!dead&&generation===loadGeneration&&error.name!=='AbortError'){loadStatus.textContent='Notes could not load. You can try Refresh again.';if(!loaded)list.replaceChildren();}return [];}
    finally{if(!dead&&generation===loadGeneration)q('[data-vb-refresh]').disabled=false;}}
  function close(){if(!dialog.open)return;dialog.close();}
  function finished(){if(dead)return;onClose();lastFocus?.isConnected&&lastFocus.focus({preventScroll:true});const next=leaveAfterClose;leaveAfterClose=null;next?.();}
  dialog.addEventListener('close',finished);q('[data-vb-close]').addEventListener('click',close);q('[data-vb-refresh]').addEventListener('click',()=>void refresh());
  dialog.addEventListener('keydown',event=>{event.stopPropagation();});dialog.addEventListener('keyup',event=>event.stopPropagation());
  function open({invite=false}={}){if(dead||dialog.open)return false;q('[data-vb-close]').textContent=leaveAfterClose?'Continue to portfolio':'Back to the garden';prompt.hidden=true;lastFocus=document.activeElement;onOpen();try{dialog.showModal();}catch(error){onClose();throw error;}void refresh();(invite?q('#vb-name'):q('[data-vb-close]')).focus({preventScroll:true});return true;}
  function dismiss(){prompt.hidden=true;const next=leave;leave=null;next?.();}
  prompt.querySelector('[data-vb-invite-skip]').addEventListener('click',dismiss);
  prompt.querySelector('[data-vb-invite-write]').addEventListener('click',()=>{leaveAfterClose=leave;leave=null;prompt.hidden=true;open({invite:true});});
  prompt.addEventListener('keydown',event=>{event.stopPropagation();if(event.key==='Escape'){event.preventDefault();dismiss();}});
  function invite({onLeave}={}){if(dead||dialog.open||!prompt.hidden){onLeave?.();return false;}leave=onLeave||null;prompt.querySelector('[data-vb-invite-skip]').textContent=onLeave?'Continue to portfolio':'Keep riding';prompt.hidden=false;if(onLeave)prompt.querySelector('[data-vb-invite-write]').focus({preventScroll:true});return true;}
  form.addEventListener('submit',async event=>{event.preventDefault();if(dead||busy)return;submitStatus.textContent='';const profile=linkedIn(q('#vb-linkedin').value);q('#vb-linkedin').setCustomValidity(profile===null?'Use a LinkedIn profile URL beginning https://www.linkedin.com/in/':'');if(!form.reportValidity())return;const name=q('#vb-name').value.trim(),feedback=q('#vb-feedback').value.trim();if(!name||!feedback){submitStatus.textContent='Please add your name and a note before posting.';submitStatus.focus();return;}busy=true;submit.disabled=true;submit.textContent='Posting...';form.setAttribute('aria-busy','true');submitStatus.textContent='Posting your note...';postAbort=new AbortController();
    try{const response=await fetch('/api/reviews',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',signal:postAbort.signal,body:JSON.stringify({name,stars:Number(new FormData(form).get('stars')),feedback,linkedin:profile,consent:true})});let result={};try{result=await response.json();}catch{}if(!response.ok)throw Error(response.status===429?'Please wait a moment before posting another note.':result.error||'Your note could not be posted. Your writing is still here; please try again.');if(dead)return;form.reset();submitStatus.textContent=result.pending?'Thank you. Your note is awaiting a check before appearing on the board.':'Thank you. Your note was received.';await refresh();submitStatus.focus({preventScroll:true});}
    catch(error){if(!dead&&error.name!=='AbortError'){submitStatus.textContent=error instanceof TypeError?'Your note could not be posted. Check your connection and try again. Your writing is still here.':error.message||'Your note could not be posted. Your writing is still here; please try again.';submitStatus.focus({preventScroll:true});}}
    finally{busy=false;if(!dead){submit.disabled=false;submit.textContent='Pin my review';form.removeAttribute('aria-busy');}}});
  q('#vb-linkedin').addEventListener('input',()=>q('#vb-linkedin').setCustomValidity(''));
  return {open,close,get isOpen(){return dialog.open;},refresh,invite,dispose(){if(dead)return;dead=true;loadAbort?.abort();postAbort?.abort();leave=null;leaveAfterClose=null;if(dialog.open)dialog.close();dialog.remove();prompt.remove();}};
}
